import { wrap, shadow, ref, text } from '../style.mjs';

// Redraws of three root beer cans marked Needs work in the 2026-11-15 review (redraw
// round 2). The rejected recipes were template cans in refreshments-12.mjs (A&W Diet,
// Diet Barq's; Diet Mug from that batch is in redraw-diet-mug-root-beer.mjs) and canned-coffee-refreshments-13.mjs (Hires).
//
// Each can is drawn from its current US 12 fl oz packshot. Two of the three catalog rows
// say "Diet" but the cans on sale now read "Zero Sugar" (same UPCs, renamed), so that is
// what the artwork reads.
//
// This file is generated: scratchpad/agents2/rootbeer/work/build.py joins body.mjs (the
// recipe code below) with the path data in *_paths.json. The path constants were made in
// three ways, noted on each: (a) vectorised from the packshot (colour-class mask, contour,
// cubic Bezier fit; coordinates are packshot pixels relative to a centre the recipe names,
// scaled by a group transform), (b) taken from a public-domain vector on Wikimedia
// Commons, (c) drawn by hand.

const r2 = n => Math.round(n * 100) / 100;

// Standard 12 fl oz can: geometry and rendering copied from the Good can() in
// classic-soda-expansion.mjs (barqs-root-beer, canada-dry-ginger-ale): body x 55..145,
// lid at y=41, foot at y=233. `over` is drawn above the house shading, for the few marks
// (white lettering on a black can) that the shading would otherwise grey.
const BODY = 'M61 41Q100 32 139 41L145 58V220Q145 233 100 233T55 220V58Z';
const drops = (n = 18, o = .28) => Array.from({ length: n }, (_, i) => `<ellipse cx="${65 + (i * 19) % 70}" cy="${65 + (i * 31) % 148}" rx="${i % 3 === 0 ? 1.2 : .7}" ry="${i % 3 === 0 ? 1.8 : 1}" fill="#fff" opacity="${o}"/>`).join('');
function can(slug, title, label, { color = '#f6f5ee', defs = '', over = '', speck = .28, bar = .21 } = {}) {
  return wrap(slug, title, `${shadow(58)}<path d="${BODY}" fill="${color}"/>
<g clip-path="${ref('bodyclip')}">${label}<path d="${BODY}" fill="${ref('shade')}"/>${over}${drops(18, speck)}<path d="M65 61V211" fill="none" stroke="#fff" stroke-opacity="${bar}" stroke-width="3"/></g>
<ellipse cx="100" cy="41" rx="39" ry="8" fill="${ref('metal')}" stroke="#9ca7a4" stroke-width="1.2"/>
<ellipse cx="100" cy="41" rx="34" ry="5.5" fill="none" stroke="#8d9892" stroke-width=".8"/>
<ellipse cx="104" cy="42" rx="8" ry="3.5" fill="#657169"/>
<path d="M93 39h10q6 0 5 4t-8 3h-6q-6-1-1-7" fill="none" stroke="#e6e8de" stroke-width="2.4"/>
<path d="M58 226q42 12 84 0" fill="none" stroke="${ref('metal')}" stroke-width="4"/>
<path d="M61 230q39 7 78 0" fill="none" stroke="#fff" stroke-opacity=".55" stroke-width="1"/>`,
  `<clipPath id="__ID__bodyclip"><path d="${BODY}"/></clipPath>${defs}`);
}
const P = (d, fill, attrs = '') => `<path d="${d}" fill="${fill}" fill-rule="evenodd" ${attrs}/>`;

