const RED = '#df0f1d', INK = '#151314';
function barrelEnd(cx, cy, rx, ry, rot, phi, offs) {
  const d = [Math.cos(phi), Math.sin(phi)], n = [-d[1], d[0]], ex = rx - 5, ey = ry - 5;
  const chords = offs.map(o => {
    const px = o * n[0], py = o * n[1];
    const A = (d[0] / ex) ** 2 + (d[1] / ey) ** 2, B = 2 * (px * d[0] / ex ** 2 + py * d[1] / ey ** 2), C = (px / ex) ** 2 + (py / ey) ** 2 - 1;
    const D = Math.sqrt(B * B - 4 * A * C), t1 = (-B - D) / (2 * A) * .84, t2 = (-B + D) / (2 * A) * .84;
    return `M${r2(px + t1 * d[0])} ${r2(py + t1 * d[1])}L${r2(px + t2 * d[0])} ${r2(py + t2 * d[1])}`;
  }).join('');
  return `<g transform="translate(${cx} ${cy}) rotate(${rot})"><ellipse rx="${rx + 10}" ry="${ry + 10}" fill="${INK}"/><ellipse rx="${rx + 3}" ry="${ry + 3}" fill="none" stroke="${RED}" stroke-width="3.5"/><ellipse rx="${ex}" ry="${ey}" fill="${RED}"/><path d="${chords}" stroke="${INK}" stroke-width="6.5" fill="none"/></g>`;
}
