// and the gold letter shadows on top, so the brown letters and rings are what is left of
// the silhouette. It is drawn as photographed: tilted, wrapped to the can's edges, its
// top-left under the foam.
function awZero() {
  const slug = 'aw-diet-root-beer', title = 'A&W Zero Sugar Root Beer';
  const sx = .113, sy = .122, BROWN = '#2b0d08';
  const g = (y, cyPx, inner) => `<g transform="translate(100 ${y}) scale(${sx} ${sy}) translate(0 ${-cyPx})">${inner}</g>`;
  // Whitewashed staves: seam positions measured on the packshot (x in icon units).
  const seam = (x, w, o, dash = '') => `<path d="M${x} 44V236" stroke="#c98f6c" stroke-width="${w}" opacity="${o}" ${dash ? `stroke-dasharray="${dash}"` : ''}/>`;
  const wood = [
    seam(75.5, 2.6, .28), seam(75.1, .7, .8, '9 1.5 14 2 6 1'), seam(76.6, .45, .6, '3 2 11 3 5 1.5'),
    seam(108.2, 1.9, .26), seam(108, .65, .8, '12 2 5 1 16 2.5'), seam(109.3, .4, .55, '4 3 8 2'),
    seam(139.6, 1.6, .3), seam(139.4, .6, .75, '7 2 13 1.5'),
    seam(66.3, .5, .5, '5 3 9 4 3 2'), seam(97.2, .45, .45, '6 4 3 2 10 5'), seam(118.6, .45, .45, '4 3 12 4 6 2'),
    seam(59.9, .5, .45, '8 3 4 2'), seam(80.9, .35, .4, '3 5 7 3'), seam(127.5, .35, .35, '5 6 3 2 9 4'), seam(89.5, .3, .3, '2 7 6 5'),
  ].join('');
  const rivet = (x, y) => `<ellipse cx="${x}" cy="${y}" rx="3.1" ry="3.3" fill="#b89384" opacity=".8"/><ellipse cx="${r2(x - .3)}" cy="${r2(y - .4)}" rx="2.6" ry="2.8" fill="#eadfd4"/><path d="M${r2(x + 1.9)} ${r2(y - 1.9)}A2.7 2.9 0 0 1 ${r2(x - .9)} ${r2(y + 2.5)}A3.4 3.4 0 0 0 ${r2(x + 1.9)} ${r2(y - 1.9)}Z" fill="#b08672" opacity=".75"/><ellipse cx="${r2(x - 1)}" cy="${r2(y - 1.1)}" rx=".9" ry=".8" fill="#fff" opacity=".8"/>`;
  const hoop = `<path d="M54 213.5Q100 222.5 146 213.5V225Q100 236 54 225Z" fill="#d6b6a5" opacity=".92"/><path d="M54 213.5Q100 222.5 146 213.5" fill="none" stroke="#b78d78" stroke-width=".8"/><path d="M54 216Q100 225 146 216" fill="none" stroke="#f3e6da" stroke-width="1" opacity=".8"/><path d="M54 223.6Q100 234.6 146 223.6" fill="none" stroke="#a9705e" stroke-width="1.3" opacity=".8"/>${rivet(67.2, 221.6)}${rivet(99, 224.4)}${rivet(132.8, 221.7)}`;
  const topHoop = `<path d="M54 74.5Q60 76 68 76.6V81.4Q60 80.8 54 79.3Z" fill="#c9a18e"/><path d="M54 74.5Q60 76 68 76.6" fill="none" stroke="#9c6a57" stroke-width=".7"/><path d="M54 79.3Q60 80.8 68 81.4" fill="none" stroke="#9c6a57" stroke-width=".7"/>`;
  const bubbles = Array.from({ length: 70 }, (_, i) => {
    const x = -390 + (i * 211) % 780, y = -600 + (i * 137) % 430, r = 5 + (i * 7) % 9;
    return `<circle cx="${x}" cy="${y}" r="${r}" fill="${i % 3 ? '#f7f1e3' : '#cdb78a'}" opacity="${i % 3 ? '.55' : '.4'}"/>`;
  }).join('');
  const logo = `${P(AW.sil, BROWN)}${P(AW.ring_out, ref('gold'))}${P(AW.ring_in, BROWN)}${P(AW.white, '#fff')}${P(AW.red, '#e3251f')}${P(AW.gold, '#c97c1e')}
${P(AW.foam, '#ece4d1')}<g clip-path="${ref('foam')}">${bubbles}${P(AW.foam_mid, '#dcc692', 'opacity=".85"')}${P(AW.foam_rim, '#c39b49', 'opacity=".9"')}</g>`;
  const band = `<path d="M-420 445Q0 483 420 445V591Q0 645 420 591Z" fill="none"/><path d="M-420 445Q0 483 420 445V591Q0 645 -420 591Z" fill="${ref('band')}"/>${P(AW.zero, '#fff')}`;
  const rb = `${P(AW.rb_out, '#cf8128')}${P(AW.rb, BROWN)}`;
  const label = `${wood}${topHoop}${hoop}<rect x="50" y="28" width="100" height="22" fill="#ece4d1"/>
${g(115.5, 0, logo)}${g(185, 541, band)}${g(204.5, 692, rb)}`;
  const defs = `<linearGradient id="__ID__gold" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#a95a0c"/><stop offset=".45" stop-color="#d18a2c"/><stop offset="1" stop-color="#b0600f"/></linearGradient>
<linearGradient id="__ID__band"><stop stop-color="#d81c19"/><stop offset=".45" stop-color="#f44a46"/><stop offset=".6" stop-color="#f24541"/><stop offset="1" stop-color="#d51a17"/></linearGradient>
<clipPath id="__ID__foam"><path d="${AW.foam}"/></clipPath>`;
  return {
    slug, family: 'aw-soda-can',
    packageChoice: 'Current US 12 fl oz (355 mL) A&W Zero Sugar Root Beer can. The catalog row says A&W Diet Root Beer; Keurig Dr Pepper renamed Diet A&W to A&W Zero Sugar and retailers state the rename on the listing for the same UPC family.',
    references: [{
      pageUrl: 'https://www.kroger.com/p/a-w-root-beer-zero-sugar-soda-cans/0007800005316',
      imageUrl: 'https://s7d1.scene7.com/is/image/kdrp/AW_RootBeer_ZeroSugar_12oz_Can_Dry?%24Dynamic-PublicURL-PNG%24=&hei=1600&wid=1600',
      inspectedAt: '2026-11-15', visuallyInspected: true,
      observations: 'Manufacturer front packshot of a standard 12 oz can (Keurig Dr Pepper image server; the Kroger listing shows the same can beside its carton). Whitewashed barrel staves with reddish seams, a riveted hoop at the foot and a stub of one at upper left. Cream root-beer foam covers the top fifth and drips over the upper left of the logo. The A&W oval is very large, tilted about 35 degrees and wraps to both edges: dark outline, gold ring, dark ring heavy at upper right, white field, red swoosh at lower left, dark-brown A and W with gold drop shadows, red ampersand outlined white. Below it a red band with white ZERO SUGAR, then dark-brown slab-serif ROOT BEER outlined gold. The can does not say Diet.',
    }],
    uncertainty: 'The logo, foam edge, ZERO SUGAR and ROOT BEER are vectorised from the packshot and follow its perspective (the band and lettering bow slightly); under the foam the logo is not drawn. Foam bubbles, wood seams, hoop and rivets are simplified by hand; the registered mark is omitted. The reference image is the manufacturer file addressed directly on its image server; I could not open the matching kdpproductfacts.com page (it renders client-side), so the product page recorded is the retailer listing that shows the same can.',
    status: 'needs-review',
    svg: can(slug, title, label, { color: '#f8f6f0', defs }),
  };
}

